import{_ as t,o as n,c as o,a4 as r}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0025 — Multilinguisme natif : un groupe de traduction porté par l'enregistrement","description":"Extrait de docs/adr/0025-multilinguisme-groupe-de-traduction.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0025 — Multilinguisme natif : un groupe de traduction porté par l'enregistrement","description":"Extrait de docs/adr/0025-multilinguisme-groupe-de-traduction.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0025-multilinguisme-groupe-de-traduction.md","filePath":"developpeurs/adr/0025-multilinguisme-groupe-de-traduction.md"}`),s={name:"developpeurs/adr/0025-multilinguisme-groupe-de-traduction.md"};function a(i,e,u,d,c,l){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0025--multilinguisme-natif--un-groupe-de-traduction-porté-par-lenregistrement" tabindex="-1">ADR-0025 — Multilinguisme natif : un groupe de traduction porté par l&#39;enregistrement <a class="header-anchor" href="#adr-0025--multilinguisme-natif--un-groupe-de-traduction-porté-par-lenregistrement" aria-label="Permalink to &quot;ADR-0025 — Multilinguisme natif : un groupe de traduction porté par l&#39;enregistrement {#adr-0025--multilinguisme-natif--un-groupe-de-traduction-porté-par-lenregistrement}&quot;">​</a></h1><p><strong>Date :</strong> 29 août 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> corpus Les MogWais <code>MULTILINGUISME_NATIF.docx</code> (propriété personnelle confirmée, cf. §17 #6 du CDC) ; CDC_CMS_AI_Native_v1.1 §3.1-3.2 (Content Engine / Field Engine), §9.2 règle 6 (termes de taxonomie), §10.2 (recherche), §14.9.7 (traduction assistée) ; complète l&#39;ADR-0021, prolonge l&#39;ADR-0013</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>La traduction assistée par IA a été livrée à l&#39;Epic E9 (§14.9.7) : un modèle propose la traduction de plusieurs champs, un traducteur l&#39;accepte, et le texte est déposé dans <code>content_entries.settings.translations[&lt;locale&gt;]</code>. La docstring d&#39;<code>app/ai_editorial/translation.py</code> nommait alors sa propre limite : <strong>rien ne sert ce texte nulle part</strong>, faute de modèle de données. <code>ContentEntry</code> n&#39;avait ni <code>locale</code>, ni notion de groupe de traduction ; <code>TaxonomyTerm</code> n&#39;avait qu&#39;un <code>label</code> ; <code>Site</code> n&#39;avait aucune langue ; la recherche indexait tout en <code>french</code>, câblé en dur ; et le Field Engine n&#39;avait aucun moyen de dire « ce champ porte du texte à traduire ».</p><p>Le corpus de référence décrit un site WordPress classique : sélecteur de langue dans l&#39;en-tête, redirection désactivée, cookie AJAX, <code>?lang=en</code>, menus déclinés. <strong>Ce dépôt n&#39;a pas de front public</strong> — <code>apps/</code> ne contient que <code>admin</code> et <code>api</code> — et n&#39;a aucune notion de menu (explicitement rejetée à la conception du multi-site, cf. <code>app/multisite/factory.py</code>). Une part importante du corpus n&#39;a donc ici rien à couvrir.</p><p>La question à trancher n&#39;est pas « comment afficher un sélecteur de langue » mais <strong>« de quelle nature est une traduction dans ce CMS »</strong> — et cette réponse décide de qui peut la publier, de ce qu&#39;il en advient à la suppression de l&#39;original, de ce que la mutualisation multi-site en fait, et de ce qu&#39;une reprise de données doit préserver.</p><p>Trois rangements étaient possibles :</p><ul><li>des <strong>colonnes sur <code>content_entries</code></strong>, chaque version linguistique étant un enregistrement à part entière ;</li><li>une <strong>table de suivi</strong> reliant un original à ses traductions, sur le modèle de <code>content_replication</code> ;</li><li>un <strong>sous-objet par locale dans <code>data</code></strong> (ou dans <code>settings</code>), une seule ligne portant toutes ses langues.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Un groupe de traduction est une paire de colonnes sur <code>ContentEntry</code></strong> : <code>locale VARCHAR(10)</code> et <code>translation_group_id UUID</code>, toutes deux nullables, assorties d&#39;un <strong>index unique partiel</strong> <code>(translation_group_id, locale) WHERE translation_group_id IS NOT NULL</code>.</p><p>Chaque version linguistique est <strong>un enregistrement autonome</strong> : même Content Type, même validation de schéma, même indexation, même cycle de vie éditorial. Elle se relit, se corrige, se publie et se dépublie par les routes qui existent déjà. La seule chose qui la distingue est qu&#39;elle partage un <code>translation_group_id</code> avec ses sœurs.</p><p>Quatre propriétés de ce choix méritent d&#39;être écrites, parce qu&#39;elles ne sont pas interchangeables :</p><ol><li><strong><code>translation_group_id</code> n&#39;a aucune clé étrangère, et ne désigne aucune ligne.</strong> C&#39;est un identifiant <em>partagé</em>, pas un renvoi vers un original. Le faire pointer vers la version française aurait fait dépendre l&#39;existence des traductions de la survie de leur source, alors qu&#39;une version anglaise publiée ne disparaît pas parce qu&#39;on a retiré la française. C&#39;est la même philosophie qu&#39;<code>origin_id</code> (E10, « la provenance est un fait, pas un lien vivant »), poussée un cran plus loin : ici, il n&#39;y a même pas de ligne à désigner.</li><li><strong>Le groupe n&#39;a pas de membre principal</strong>, et c&#39;est ce qui permet de l&#39;interroger depuis n&#39;importe lequel — <code>GET /content-types/{key}/entries/{id}/translations</code> répond aussi bien depuis la version anglaise que depuis la française.</li><li><strong>Le groupe naît à la première traduction, pas à la création du contenu.</strong> Un groupe d&#39;un seul membre ne relie rien ; en ouvrir un pour chaque enregistrement du CMS aurait rempli une colonne d&#39;identifiants sans objet.</li><li><strong>L&#39;unicité <code>(groupe, langue)</code> est une contrainte de base, pas une vérification applicative.</strong> « Quelle est la version anglaise de ce contenu ? » est la seule question que ce groupe existe pour trancher : deux réponses possibles, et il ne sert plus à rien. La route traduit le refus en 409 nommé (« la version anglaise existe déjà »), pour qu&#39;une violation de contrainte ne remonte pas en 500.</li></ol><p><strong>Pourquoi pas une table de suivi.</strong> <code>content_replication</code> en est une, et elle est justifiée : une réplique se resynchronise, donc elle a un statut, une empreinte, une date de dernier sync et des conflits à arbitrer. Un groupe de traduction n&#39;a <strong>rien de comparable à suivre</strong> — aucune synchronisation n&#39;a lieu entre deux versions linguistiques, par construction : le CDC §14.4 pose que l&#39;IA propose et qu&#39;un humain décide, et une traduction qui se remettrait à jour toute seule depuis sa source écraserait le travail d&#39;un traducteur. Deux colonnes suffisent ; une table de plus aurait été de la structure sans fonction, et une jointure de plus sur tous les chemins de lecture du contenu.</p><p><strong><code>TaxonomyTerm</code> gagne un <code>labels: JSONB</code> (<code>{locale: intitulé}</code>), et reste une seule ligne par terme.</strong> C&#39;est l&#39;inverse exact du choix fait pour les contenus, et pour une raison qui tient à ce qu&#39;est un terme : une entité dont l&#39;intitulé varie, pas un groupe d&#39;entités. Dupliquer les lignes par locale aurait donné à « Écoles » et « Schools » deux slugs distincts, donc deux fusions multi-sites indépendantes, et la règle 6 du CDC §9.2 aurait eu à arbitrer des conflits entre deux traductions d&#39;une même chose.</p><p><code>label</code> <strong>reste l&#39;intitulé de référence</strong> : c&#39;est lui qui dérive le slug (ADR-0021), lui que compare la fusion inter-sites, et lui qui répond quand la langue demandée n&#39;est pas traduite. <code>labels</code> est donc <strong>orthogonal à la détection de conflit</strong> : deux sites d&#39;accord sur l&#39;intitulé de référence sont d&#39;accord sur le terme, qu&#39;ils l&#39;aient ou non traduit dans les mêmes langues. À la fusion, les traductions de la source s&#39;<strong>ajoutent</strong> à celles de la cible sans les écraser — une traduction connue de A et absente de B est un gain ; une traduction que les deux ont écrite différemment est un désaccord, et l&#39;écraser au passage d&#39;une synchronisation serait la fusion silencieuse que le CDC interdit.</p><p><strong><code>Site</code> gagne <code>default_locale</code> (non nul, défaut <code>&#39;fr&#39;</code>) et <code>available_locales</code> (<code>text[]</code>, non nul, défaut <code>{fr}</code>).</strong> Colonnes dédiées, pas des clés de <code>settings</code> : <code>settings</code> est un dictionnaire de namespaces où un Epic pose ce qui lui est propre, la langue par défaut d&#39;un site est un fait structurel du Core, au même titre que <code>contact_email</code> ou <code>analytics_id</code>. Le type <code>text[]</code> reprend le motif de <code>search_index.taxonomies</code> (E13) pour un tableau de chaînes, plutôt que d&#39;introduire un JSONB de plus — un tableau Postgres se filtre avec <code>= ANY</code>.</p><p><strong><code>BaseFieldDef</code> gagne <code>translatable: bool = False</code>.</strong> Porté par la classe mère, donc par les 30 types de champs sans exception, exactement comme <code>contains_personal_data</code> (E5) et pour la même raison : un drapeau déclaré type par type aurait manqué au premier type ajouté après coup. Défaut <code>False</code> — un numéro de référence, une couleur, une géolocalisation ne se traduisent pas. Comme <code>contains_personal_data</code>, <strong>c&#39;est un attribut du schéma déclaré, pas une clé de la donnée</strong> : il ne crée aucun champ à valider et ne change pas la forme de <code>content_entries.data</code>, ce qui permet de le poser sur un Content Type existant sans invalider un seul de ses enregistrements.</p><p><strong>L&#39;indexation lexicale dérive sa configuration de la langue de l&#39;enregistrement</strong>, avec repli total sur <code>french</code>. <code>app/listing/indexing.py</code> était câblé en dur ; il porte désormais une correspondance locale → configuration PostgreSQL, restreinte aux configurations réellement présentes dans l&#39;image du projet (<code>pgvector/pgvector:pg16</code>, 29 configurations standard). Une langue inconnue, une région (<code>pt-BR</code> → <code>portuguese</code>) ou une locale nulle retombent sur <code>french</code> : aucun enregistrement existant ne change de comportement, et <strong>aucune réindexation n&#39;est déclenchée</strong>.</p><p><strong>La traduction assistée gagne une dérivation, pas un nouveau contrat.</strong> <code>TranslationSuggestIn.fields</code> devient facultatif : absent, la route lit le schéma du Content Type visé, retient les champs <code>translatable</code> et prend leurs valeurs courantes. <code>TranslationRequest.fields</code> reste obligatoire côté service, qui continue de ne relire aucun Content Type. Deux refus explicites remplacent l&#39;appel vide au modèle : sans enregistrement visé, il n&#39;y a aucun schéma d&#39;où déduire quoi que ce soit ; sans champ <code>translatable</code> renseigné, le problème est dans le schéma ou dans le contenu, pas chez le fournisseur d&#39;IA.</p><p><strong>Périmètre : données et API. Aucun front public, aucune UI admin.</strong> Cette passe rend les contenus, les termes et les sites <em>capables</em> de porter plusieurs langues, et l&#39;expose par l&#39;API. Le sélecteur de langue, le routage par URL et la redirection reviennent au consommateur de cette API — ils ne peuvent pas être construits ici, faute de front public à construire dedans. Aucun écran Nuxt de gestion des groupes de traduction n&#39;est livré non plus : ce sera un lot ultérieur si voulu.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Table de suivi <code>content_translation</code> (sur le modèle de <code>content_replication</code>)</strong></td><td>Écartée : elle porterait un statut de synchronisation qui n&#39;existe pas. Deux versions linguistiques ne se resynchronisent jamais l&#39;une sur l&#39;autre (§14.4 : l&#39;IA propose, l&#39;humain décide), il n&#39;y a donc ni empreinte à comparer, ni conflit à arbitrer, ni date de dernier sync à tenir. La table n&#39;aurait porté que ce que deux colonnes portent déjà, au prix d&#39;une jointure sur tous les chemins de lecture du contenu.</td></tr><tr><td><strong>Un sous-objet par locale dans <code>data</code> (une ligne, toutes ses langues)</strong></td><td>Écartée pour trois raisons cumulatives : la validation de schéma du Field Engine porte sur un objet plat (<code>validate_entry_data</code>) et aurait dû devenir consciente des locales ; le cycle de vie (E4) est <strong>par ligne</strong>, donc publier la version anglaise aurait publié la française du même geste ; et l&#39;index lexical est par ligne lui aussi, donc une seule configuration linguistique pour toutes les langues du contenu — c&#39;est-à-dire précisément le défaut qu&#39;on corrige.</td></tr><tr><td><strong>Réutiliser <code>origin_id</code> / <code>origin_site_id</code> pour relier une traduction à sa source</strong></td><td>Écartée, et c&#39;était le piège le plus coûteux : ces deux colonnes sont câblées dans <code>app/multisite/guards.py</code>, où une valeur non nulle déclenche le refus d&#39;écriture de la règle 1. Une traduction y aurait été traitée comme une réplique multi-site, donc <strong>non modifiable par son propre traducteur</strong> — un défaut qui ne se serait vu qu&#39;à la première correction.</td></tr><tr><td><strong>Lignes <code>taxonomy_terms</code> dupliquées par locale</strong></td><td>Écartée : un terme est une entité dont l&#39;intitulé varie. Dupliquer aurait produit deux slugs, donc deux entrées indépendantes dans le registre par site (ADR-0021), donc des conflits de règle 6 entre deux traductions d&#39;un même terme — un arbitrage demandé à un humain sur une question qui n&#39;en est pas une.</td></tr><tr><td><strong><code>sites.settings[&#39;i18n&#39;]</code> plutôt que deux colonnes</strong></td><td>Écartée : <code>settings</code> accueille ce qu&#39;un Epic ajoute sans migration, pas ce dont dépend l&#39;interprétation des données. La langue par défaut d&#39;un site décide de ce qu&#39;un consommateur sert par défaut ; comme <code>contact_email</code> et <code>analytics_id</code>, elle mérite une colonne que l&#39;usine à sites puisse exiger.</td></tr><tr><td><strong>Liste fermée de langues autorisées dans le Core</strong></td><td>Écartée : ajouter le breton serait devenu un déploiement de code — exactement ce que le critère de recette n°1 du CDC (§3.1) interdit pour un Content Type, et il n&#39;y a aucune raison que la langue y échappe. Ce qui est vérifié est la <strong>forme</strong> (BCP 47 abrégé) ; le catalogue est une donnée (<code>sites.available_locales</code>).</td></tr><tr><td><strong>Faire voyager <code>translation_group_id</code> avec les copies mutualisées</strong></td><td>Écartée : l&#39;unicité <code>(groupe, langue)</code> est globale, donc deux sites cibles produiraient deux copies au même couple et la deuxième réplication échouerait. Et un groupe de traduction est un ensemble de contenus qu&#39;on édite ensemble, or une copie ne s&#39;édite pas là où elle arrive (règle 1). La <strong>langue</strong>, elle, voyage : c&#39;est un fait du contenu, et le site d&#39;accueil doit l&#39;indexer avec le bon dictionnaire.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Ouvrir la version anglaise d&#39;un contenu ne demande <strong>ni migration, ni code Core</strong> : c&#39;est une écriture de données sur un Content Type quelconque, y compris inventé cinq minutes plus tôt. Le critère de recette n°1 (§3.1) reste vrai en multilingue.</li><li>Chaque version linguistique a son propre cycle de vie éditorial : on peut publier la française et garder l&#39;anglaise en relecture, ce qu&#39;aucun rangement « toutes les langues dans une ligne » ne permet.</li><li>La suppression d&#39;une version ne casse rien des autres — il n&#39;y a pas de ligne maîtresse à protéger.</li><li><strong>Le point ouvert laissé par l&#39;ADR-0013 se referme de lui-même</strong> : <code>settings.seo</code> n&#39;a pas à être décliné par locale, puisque chaque traduction est un enregistrement autonome avec son propre panneau de configuration, donc ses propres métadonnées SEO, son propre slug et son propre surtitre.</li><li>La recherche cesse d&#39;indexer l&#39;anglais avec le dictionnaire français, sans réindexation ni régression sur le corpus existant.</li><li>La traduction assistée d&#39;E9 cesse d&#39;exiger que l&#39;appelant sache quels champs se traduisent : cette connaissance est dans le schéma, et la recopier côté client aurait garanti qu&#39;elle s&#39;en écarte au premier champ ajouté.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Rien de tout cela n&#39;est visible pour un visiteur.</strong> Ce lot ne sert aucune page dans aucune langue ; il rend le service possible. Tant qu&#39;aucun consommateur ne l&#39;exploite, le multilinguisme reste une capacité de l&#39;API — c&#39;est le garde-fou de cette ADR, et il est assumé plutôt que découvert.</li><li><strong>Aucune UI de gestion.</strong> Créer et suivre un groupe de traduction se fait par l&#39;API ; un agent sans back-office dédié ne peut pas le faire seul.</li><li><strong>Une traduction ne se resynchronise jamais depuis sa source.</strong> C&#39;est voulu (§14.4), mais cela signifie qu&#39;une correction du texte français ne signale rien du côté anglais : personne n&#39;est averti que la traduction a vieilli. Un indicateur de fraîcheur (comparer les empreintes des membres d&#39;un groupe) est possible plus tard sans changer ce modèle — la donnée nécessaire est déjà là (<code>content_hash</code>).</li><li><strong>La langue d&#39;une copie mutualisée ne se corrige qu&#39;à la prochaine écriture du contenu source.</strong> <code>locale</code> ne participe pas à <code>content_hash</code> : l&#39;y ajouter aurait invalidé d&#39;un coup l&#39;empreinte de toutes les copies déjà en place et déclenché une resynchronisation générale au premier balayage, pour une colonne qu&#39;aucune d&#39;entre elles ne portait.</li><li><strong><code>settings.translations</code> (E9) et les groupes de traduction cohabitent sans se recouvrir.</strong> Le premier est un dépôt de propositions relues, le second porte le contenu publié ; un traducteur recopie l&#39;un dans l&#39;autre. Automatiser ce passage — appliquer une suggestion acceptée directement dans le membre du groupe correspondant — est un raccourci évident qui reste à écrire, et son absence doit être connue.</li><li><strong><code>PostgreSQL</code> n&#39;a pas de dictionnaire pour toutes les langues.</strong> Le breton, le corse et l&#39;occitan, que des collectivités françaises servent réellement, retombent sur <code>french</code>. C&#39;est un repli honnête, pas une équivalence : la racinisation y sera approximative.</li><li>Le retour arrière de la migration 0016 <strong>perd les traductions de termes</strong> (<code>labels</code>) : elles n&#39;ont pas d&#39;autre logement dans le schéma précédent, et les replier dans un JSONB de secours aurait laissé des données orphelines qu&#39;aucun code ne relit.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Front public : sélecteur de langue, routage par URL, repli sur <code>sites.default_locale</code> quand une version linguistique manque. <strong>Fait le 07/10/2026</strong> (lot 12, issue #6). Partie API (<a href="/teuthis-cms-distribution/developpeurs/adr/0066-pages-multilingues">ADR-0066</a>) : les pages ont une langue et un groupe de traduction, <code>/public/resolve</code> résout <code>/en/…</code> et <code>/en</code> et rend les <code>alternates</code> d&#39;une page, le descripteur rend <code>home_paths</code> (l&#39;accueil de chaque langue, base du repli), <code>GET /sitemap?locale=</code> rend l&#39;arbre d&#39;une langue ; preuve <code>tests/test_pages_multilingues.py</code>. Reste la partie front (<code>apps/front</code>, lot 12). Partie front : <code>apps/front</code> lit la langue dans le premier segment du chemin, sert le menu par langue (<code>/sitemap?locale=</code>), rend <code>&lt;html lang&gt;</code>, les <code>&lt;link rel=&quot;alternate&quot; hreflang&gt;</code> et le sélecteur <code>components/socle/SelecteurLangue.vue</code> (repli : accueil de la langue, puis accueil par défaut) ; preuves <code>tests/unitaires/multilingue.test.ts</code> et <code>tests/a11y/lancer.mjs</code> (<code>/en</code>, <code>/en/about</code>, 0 violation axe).</li><li>[x] Back-office Nuxt : écran de gestion d&#39;un groupe de traduction (ouvrir une langue, voir ce qui manque, ce qui a vieilli). <strong>Fait le 30/09/2026</strong> — la fiche d&#39;un contenu liste ses versions, ouvre une langue manquante (<code>647c504</code>) et dit ce qui a vieilli, champ par champ, avec « Marquer à jour » (<code>apps/admin/pages/contenus/[key]/[id].vue</code>, <code>server/api/content-types/[key]/entries/[id]/translations/mark-current.post.ts</code>).</li><li>[x] Epic IA : appliquer une suggestion de traduction acceptée directement dans le membre du groupe visé, plutôt que dans <code>settings.translations</code>. <strong>Fait le 04/10/2026</strong> — décision du Product Owner : seulement si le membre de la langue visée existe déjà ; ses champs <code>translatable</code> sont remplacés (validation Field Engine, réindexation, propagation, journal comme l&#39;édition manuelle), il garde son état éditorial, et sa fraîcheur est reposée sur la source par <code>stamp_translation</code> (comme « Marquer à jour ») quand la proposition couvre tous les champs traduisibles. Sinon — membre absent, copie mutualisée (règle 1), aucun champ traduisible proposé — dépôt inchangé dans <code>settings.translations</code>. La route rend <code>written_to</code> (<code>member</code> / <code>settings</code>) et <code>member_id</code> (<code>app/ai_editorial/translation.py</code>, <code>app/api/ai_editorial.py</code>, <code>apps/admin/pages/ia/suggestions.vue</code>) ; preuve : <code>tests/test_traduction_appliquee_au_membre.py</code> (5 tests, 3 rouges sans le code).</li><li>[x] Indicateur de fraîcheur d&#39;une traduction, par comparaison des empreintes des membres d&#39;un groupe — côté API : chaque traduction retient sa source et l&#39;empreinte de ses champs traduisibles, globale et par champ (migration <code>0045_fraicheur_des_traductions.py</code>, <code>app/content/i18n.py</code>, <code>app/content/freshness.py</code>) ; <code>GET …/translations</code> rend <code>freshness</code> par membre (<code>source</code> / <code>a_jour</code> / <code>a_revoir</code> / <code>inconnue</code>, champs vieillis nommés) et <code>POST …/translations/mark-current</code> déclare une traduction à jour (<code>tests/test_fraicheur_des_traductions.py</code>). écran : <code>apps/admin/pages/contenus/[key]/[id].vue</code> (statut par version, bouton « Marquer à jour »).</li></ul>',30)])])}const m=t(s,[["render",a]]);export{g as __pageData,m as default};
